#!/usr/bin/env bash
# The whole of session A and session B in DRY mode, on the laptop, as a transcript
# (docs/gpu-experiments/02-validation/02-session-plan.md; the appendix docs/gpu-experiments/02-validation/05-rehearsal.md is this output).
#
#   bash env/session/rehearse.sh [> docs/gpu-experiments/02-validation/05-rehearsal.md]
#
# Nothing is provisioned, copied or run: laptop.sh prints its TUI, ssh and rsync commands,
# vm.sh prints its stage commands and queue.sh prints one run_fleet.py line per queue row.
# The point is that every command of the plan exists, parses and is spelled the way the
# scripts spell it; a typo in a queue file or a stage name fails here, not on the VM.
set -uo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$ROOT" || exit 1
export DRY=1 TUI="echo TUI" VM_IP_FILE=/tmp/rehearse.vm.ip LOGDIR=/tmp/rehearse.logs RECORD=/tmp/rehearse.record \
       FLEET_OUT=/tmp/rehearse.fleet_out SNAP=/model/snapshot REF_DIR=/tmp/rehearse.ref PY="$ROOT/.venv/bin/python"
rm -rf /tmp/rehearse.logs /tmp/rehearse.record /tmp/rehearse.fleet_out /tmp/rehearse.ref; mkdir -p /tmp/rehearse.ref
: > /tmp/rehearse.ref/ref_cache.safetensors
L="bash env/session/laptop.sh"; V="bash env/session/vm.sh"

h() { echo; echo "### $*"; echo; }
show() { echo '```'; "$@" 2>&1 | grep -v "^== \|^+ setsid" ; echo '```'; }

main() {
echo "# 05 - Rehearsal: every command of the two sessions, in DRY mode"
echo
echo "Generated by \`env/session/rehearse.sh\` on $(date -u +%Y-%m-%dT%H:%MZ). Each block is the"
echo "exact command the scripts run; \`+\` lines are what the VM or the laptop would execute."
echo "The laptop side is shown with the TUI replaced by \`echo TUI\` and the address 0.0.0.0."

h "Session A, minute 0: provision, address, push"
show $L provision
show $L push

h "Session A, minute 2: the model, the image and the build in parallel; the record if the host is new"
show $L start download
show $L start image
show $L start setup
show $L start hw
echo "On the VM those become:"
show $V download
show $V image
show $V setup

h "Session A, minute 25: the day-1 checks, the reference and the kernel tests"
show $V checks
show $V reference
show $V kernels

h "Session A, minute 32: the fault (queue-a.txt)"
show $V queue env/session/queue-a.txt

h "Session A, minute 40: the bisection over layer 7 (labels of queue-fault.txt)"
echo '```'; echo "+ bash env/session/vm.sh start bisect env/session/queue-fault.txt -- --layers 8 --head --iters 2"; echo '```'

h "Session A, row A4: the pre-baked fixes (queue-fix.txt)"
show $V queue env/session/queue-fix.txt

h "Session A, minutes 80 to 240: after the fix (queue-a2.txt)"
show $V queue env/session/queue-a2.txt

h "Every 30 minutes and at the end: pull, then delete"
show $L pull
show $L delete --yes

h "Session B: the measurements (queue-b.txt)"
show $V queue env/session/queue-b.txt

echo
echo "Status files after the rehearsal (the rows every real run appends to):"
echo '```'; sed 's/^[0-9T:Z-]* //' /tmp/rehearse.logs/queue.status 2>/dev/null | sort -u | head -40; echo '```'
}

# the laptop's own path is not part of the record
main | sed "s#$ROOT#<repo>#g"
